#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。"""

import csv
import sys


def count_non_null(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.DictReader(f)
        if reader.fieldnames is None:
            return counts
        for name in reader.fieldnames:
            counts[name] = 0
        for row in reader:
            for name in reader.fieldnames:
                value = row.get(name)
                if value is not None and value.strip() != "":
                    counts[name] += 1
    return counts


def main():
    if len(sys.argv) != 2:
        print(f"用法: {sys.argv[0]} <csv文件>", file=sys.stderr)
        sys.exit(1)
    counts = count_non_null(sys.argv[1])
    if not counts:
        print("文件为空或没有表头", file=sys.stderr)
        sys.exit(1)
    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name:<{width}}  {count}")


if __name__ == "__main__":
    main()
